import 'wg_config.dart';

/// Deterministic WireGuard serialiser.
///
/// Used for (a) handing a config to the platform tunnel and (b) letting a
/// user export what they imported. Output is stable so it can be diffed and
/// fingerprinted in tests.
class WgSerializer {
	const WgSerializer._();

	static const String headerComment =
		'# Generated by Phantrix. Keys in this file are private; treat the file as a secret.';

	static String serialize(WgConfig config, {bool includePrivateKey = true}) {
		final buffer = StringBuffer(headerComment);
		buffer.writeln();
		buffer.writeln('[Interface]');
		buffer.writeln('PrivateKey = ${includePrivateKey ? config.interface.privateKey : ''}');
		buffer.write('Address = ');
		buffer.writeln(config.interface.addresses.map((a) => a.toString()).join(', '));
		if (config.interface.dns.isNotEmpty) {
			buffer.writeln('DNS = ${config.interface.dns.join(', ')}');
		}
		final mtu = config.interface.mtu;
		if (mtu != null) {
			buffer.writeln('MTU = $mtu');
		}
		final listenPort = config.interface.listenPort;
		if (listenPort != null && listenPort > 0) {
			buffer.writeln('ListenPort = $listenPort');
		}
		for (final peer in config.peers) {
			buffer.writeln();
			buffer.writeln('[Peer]');
			buffer.writeln('PublicKey = ${peer.publicKey}');
			final psk = peer.presharedKey;
			if (psk != null && psk.isNotEmpty) {
				buffer.writeln('PresharedKey = $psk');
			}
			final endpoint = peer.endpoint;
			if (endpoint != null) {
				buffer.writeln('Endpoint = ${endpoint.display}');
			}
			buffer.writeln(
				'AllowedIPs = ${peer.allowedIps.map((i) => i.toString()).join(', ')}',
			);
			final keepalive = peer.persistentKeepalive;
			if (keepalive != null && keepalive > 0) {
				buffer.writeln('PersistentKeepalive = $keepalive');
			}
		}
		return buffer.toString();
	}

	/// A stable, non-secret fingerprint used to detect duplicate servers.
	static String fingerprint(WgConfig config) {
		final peers = config.peers.map((p) {
			final endpoint = p.endpoint?.display ?? '';
			final allowed = [...p.allowedIps.map((i) => i.toString())]..sort();
			return '${p.publicKey}|$endpoint|${allowed.join(',')}';
		}).toList()
			..sort();
		final addresses = [...config.interface.addresses.map((a) => a.toString())]..sort();
		return '$addresses|${peers.join(';')}';
	}
}
